-- Canonical aliases for saved-skill rediscovery. Keeps scoring weights and
-- existing match records/decisions unchanged; required skills outrank preferred.
create or replace function todo_internal.canonical_skill(p_skill text)
returns text language sql immutable set search_path = '' as $skill$
with raw as (
 select regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(lower(coalesce(p_skill,'')), '&', ' and ', 'g'), 'asp\s*\.\s*net', ' aspdotnet ', 'g'), '\.\s*net', ' dotnet ', 'g'), 'c\s*\+\s*\+', ' cplusplus ', 'g'), 'c\s*#', ' csharp ', 'g'), '([a-z])\.(?=[a-z])', '\1', 'g') as value
), compact as (
 select btrim(regexp_replace(regexp_replace(value, '[^a-z0-9+ ]', ' ', 'g'), '\s+', ' ', 'g')) as key from raw
)
