CREATE OR REPLACE FUNCTION todo_internal.calculate_candidate_requirement_match(p_candidate_id uuid, p_requirement_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'todo_internal'
AS $function$
declare
  c record;
  r record;
  cand_skills text[];
  mand_skills text[];
  pref_skills text[];
  matched_mand text[];
  matched_pref text[];
  missing_mand text[];
  mandatory_ratio numeric := 0;
  preferred_ratio numeric := 0;
  experience_ratio numeric := 0;
  location_ratio numeric := 0;
  weighted_points numeric := 0;
  total_weight numeric := 0;
  score numeric := 0;
  rec screening_recommendation;
begin
  select id, skills, total_experience, relevant_experience, current_location, preferred_location
  into c from public.candidates where id = p_candidate_id;
  if not found then return; end if;

  select id, mandatory_skills, preferred_skills, experience_min, experience_max, location, status
  into r from public.requirements where id = p_requirement_id;
  if not found then return; end if;

  cand_skills := array(select distinct todo_internal.canonical_skill(x) from unnest(coalesce(c.skills,array[]::text[])) x where trim(coalesce(x,''))<>'');
  mand_skills := array(select distinct todo_internal.canonical_skill(x) from unnest(coalesce(r.mandatory_skills,array[]::text[])) x where trim(coalesce(x,''))<>'');
  pref_skills := array(select distinct todo_internal.canonical_skill(x) from unnest(coalesce(r.preferred_skills,array[]::text[])) x where trim(coalesce(x,''))<>'');

  pref_skills := array(select x from unnest(pref_skills) x where not (x=any(mand_skills)));

  matched_mand := array(select x from unnest(mand_skills) x where x=any(cand_skills));
  matched_pref := array(select x from unnest(pref_skills) x where x=any(cand_skills));
  missing_mand := array(select x from unnest(mand_skills) x where not (x=any(cand_skills)));

  if cardinality(mand_skills)>0 then
    mandatory_ratio := cardinality(matched_mand)::numeric/cardinality(mand_skills);
    weighted_points := weighted_points + mandatory_ratio*60;
    total_weight := total_weight + 60;
  end if;

  if cardinality(pref_skills)>0 then
    preferred_ratio := cardinality(matched_pref)::numeric/cardinality(pref_skills);
    weighted_points := weighted_points + preferred_ratio*15;
    total_weight := total_weight + 15;
  end if;

  if r.experience_min is not null or r.experience_max is not null then
    if (r.experience_min is null or coalesce(c.relevant_experience,c.total_experience,0)>=r.experience_min)
       and (r.experience_max is null or coalesce(c.relevant_experience,c.total_experience,0)<=r.experience_max) then
      experience_ratio := 1;
    elsif r.experience_min is not null and coalesce(c.relevant_experience,c.total_experience,0)>=greatest(r.experience_min-1,0) then
      experience_ratio := 0.5;
    else
      experience_ratio := 0;
    end if;
    weighted_points := weighted_points + experience_ratio*15;
    total_weight := total_weight + 15;
  end if;

  if nullif(trim(coalesce(r.location,'')),'') is not null then
    if lower(coalesce(c.current_location,'')) like '%'||lower(trim(r.location))||'%'
       or lower(coalesce(c.preferred_location,'')) like '%'||lower(trim(r.location))||'%'
       or (nullif(trim(coalesce(c.current_location,'')),'') is not null and lower(trim(r.location)) like '%'||lower(trim(c.current_location))||'%')
       or (nullif(trim(coalesce(c.preferred_location,'')),'') is not null and lower(trim(r.location)) like '%'||lower(trim(c.preferred_location))||'%') then
      location_ratio := 1;
    end if;
    weighted_points := weighted_points + location_ratio*10;
    total_weight := total_weight + 10;
  end if;

  if total_weight > 0 then score := round((weighted_points/total_weight*100)::numeric,2); else score := 0; end if;

  rec := case
    when total_weight=0 then 'Not Suitable'::screening_recommendation
    when score>=80 and (cardinality(mand_skills)=0 or mandatory_ratio>=0.75) then 'Strong Match'::screening_recommendation
    when score>=55 then 'Review Recommended'::screening_recommendation
    else 'Not Suitable'::screening_recommendation
  end;

  insert into public.candidate_requirement_matches(candidate_id,requirement_id,match_score,matching_skills,missing_skills,recommendation,last_calculated_at,ignored)
  values(p_candidate_id,p_requirement_id,score,
    array(select distinct x from unnest(coalesce(matched_mand,array[]::text[])||coalesce(matched_pref,array[]::text[])) x),
    coalesce(missing_mand,array[]::text[]),rec,now(),false)
  on conflict(candidate_id,requirement_id) do update set
    match_score=excluded.match_score,
    matching_skills=excluded.matching_skills,
    missing_skills=excluded.missing_skills,
    recommendation=excluded.recommendation,
    last_calculated_at=excluded.last_calculated_at;
end;
$function$;


do $check$
begin
 if todo_internal.canonical_skill('Microsoft SQL Server (MS SQL)') <> todo_internal.canonical_skill('MSSQL') then raise exception 'SQL Server alias mismatch'; end if;
 if todo_internal.canonical_skill('ReactJS') <> todo_internal.canonical_skill('React.js') then raise exception 'React alias mismatch'; end if;
 if todo_internal.canonical_skill('Oracle PLSQL') <> todo_internal.canonical_skill('PL/SQL') then raise exception 'PL/SQL alias mismatch'; end if;
 if todo_internal.canonical_skill('.NET Core') = todo_internal.canonical_skill('.NET Framework') then raise exception 'Distinct .NET families collapsed'; end if;
 if todo_internal.canonical_skill('Angular 19+') = todo_internal.canonical_skill('Angular 18') then raise exception 'Version condition collapsed'; end if;
end;
$check$;
